<script setup>
import { SHOPPING_OPERATION_PAGE_EVENTS, SHOPPING_OPERATION_PAGE_PROPS, localizeOperationPage } from './shopping-operation-page-contract'
const props=defineProps(SHOPPING_OPERATION_PAGE_PROPS); const emit=defineEmits(SHOPPING_OPERATION_PAGE_EVENTS); const l=(zh,en)=>localizeOperationPage(props.languageBase,zh,en)
</script>
<template>
<main class="cu-ops" :data-page="pageKey" data-testid="shopping-store-operation-page"><header class="cu-opbar"><button @click="emit('back')">←</button><strong>CU</strong><span>NICE TO CU</span><div><button data-testid="shopping-open-service" @click="emit('open-service')"><i class="fas fa-circle-question"></i></button><button @click="emit('open-orders')"><i class="fas fa-clock-rotate-left"></i></button><button @click="emit('open-cart')"><i class="fas fa-basket-shopping"></i><b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>
    <section v-if="pageKey==='cart'" id="shopping-cart" class="cu-bag"><header><div><span>PICKUP BAG / SEONGSU 04</span><h1>{{ l('这家门店，十二分钟后见','Meet this store in twelve minutes') }}</h1><p>{{ l('快取袋只读取当前门店库存，不混入其他门店或配送订单。','The pickup bag reads only this store’s stock and never mixes other branches or delivery orders.') }}</p></div><div class="cu-countdown"><small>READY IN</small><b>12:00</b><span>{{ cartQuantity }} ITEMS</span></div></header><section class="cu-store-strip"><i class="fas fa-location-dot"></i><div><small>PICKUP STORE</small><strong>SEONGSU 04 / 320M</strong></div><button>CHANGE</button></section><div v-if="!cartItems.length" class="cu-empty">PICKUP BAG EMPTY</div><div v-else class="cu-bag-layout"><section><article v-for="line in cartItems" :key="line.productId"><span class="cu-item"><img v-if="productImageUrl(line.product)" :src="productImageUrl(line.product)" :alt="productDisplayTitle(line.product)" /><i v-else :class="productCategoryIcon(line.product)"></i><em>IN STORE</em></span><div><small>ZONE {{ line.product.category==='grocery'?'COLD':'A' }}</small><strong>{{ productDisplayTitle(line.product) }}</strong><b>{{ formatOrderItemSubtotal({ ...line,unitPriceCents:line.product.priceCents,currency:line.currency }) }}</b><div><button @click="emit('update-quantity',line.productId,-1)">−</button><span>{{ line.quantity }}</span><button @click="emit('update-quantity',line.productId,1)">+</button></div></div></article></section><aside><p>PICKUP REVIEW</p><strong>{{ cartTotalLabel }}</strong><div class="cu-flow"><span>1 ORDER</span><i></i><span>2 READY</span><i></i><span>3 SCAN</span></div><label><input :checked="giftEnabled" type="checkbox" data-testid="shopping-gift-enabled" @change="emit('update:giftEnabled',$event.target.checked)" /> PICKUP GIFT</label><select v-if="giftEnabled" :value="giftContactId" data-testid="shopping-gift-contact" @change="emit('update:giftContactId',$event.target.value)"><option value="">MANUAL RECIPIENT</option><option v-for="contact in giftRecipientOptions" :key="contact.id" :value="String(contact.id)">{{ contact.name }}</option></select><input v-if="giftEnabled" :value="giftRecipientName" data-testid="shopping-gift-name" @input="emit('update:giftRecipientName',$event.target.value)" /><button data-testid="shopping-checkout" @click="emit('checkout')">PLACE STORE PICKUP</button></aside></div></section>
    <section v-else-if="pageKey==='orders'" id="shopping-orders" class="cu-pickups"><header><div><span>NEARBY PICKUPS</span><h1>{{ l('门店取货记录','Store pickup records') }}</h1></div><button @click="emit('open-logistics')">STORE STATUS →</button></header><article v-for="order in orders" :key="order.id" :data-testid="`shopping-order-${order.id}`"><div class="cu-qr"><i class="fas fa-qrcode"></i></div><div><small>SEONGSU 04 / {{ formatLogisticsDate(order.createdAt) }}</small><h2>{{ order.items.map(x=>x.title).join(' / ') }}</h2><p>{{ order.itemCount }} ITEMS · {{ formatOrderTotal(order) }}</p><b>{{ orderStatusLabel(order.status) }}</b></div><button :data-testid="`shopping-open-order-detail-${order.id}`" @click="emit('open-order',order.id)">PICKUP PASS</button><button @click="emit('delete-order',order.id)">×</button></article><div v-if="!orders.length" class="cu-empty">NO PICKUPS</div></section>
    <section v-else-if="pageKey==='logistics'" class="cu-status" data-testid="shopping-logistics-panel"><header><button @click="emit('open-orders')">← PICKUPS</button><span>STORE STATUS / NOW</span><h1>{{ l('门店正在为你备货','The store is preparing your pickup') }}</h1></header><article v-for="row in logisticsRows" :key="row.order.id" :data-testid="`shopping-logistics-order-${row.order.id}`"><div class="cu-status-light"><span></span><b>{{ row.latestEvent?'READY':'PREP' }}</b></div><div><small>{{ row.latestEvent?logisticsEventTypeLabel(row.latestEvent.type):'STORE PREPARING' }}</small><h2>{{ row.title }}</h2><p>{{ row.latestEvent?.summary||row.summary }}</p><b :data-testid="`shopping-logistics-status-${row.order.id}`">{{ logisticsStatusLabel(row.status) }}</b><em v-if="row.latestEvent" :data-testid="`shopping-logistics-latest-event-${row.order.id}`">{{ row.latestEvent.pickupPoint||row.latestEvent.locationHint }}</em></div><button :data-testid="`shopping-logistics-detail-${row.order.id}`" @click="emit('open-order',row.order.id)">OPEN PASS</button></article><div v-if="!logisticsRows.length" class="cu-empty">NO STORE STATUS</div></section>
    <section v-else-if="selectedOrder" class="cu-detail" data-testid="shopping-order-detail-panel"><header><button data-testid="shopping-close-order-detail" @click="emit('close-order')">←</button><div><span>PICKUP PASS / SEONGSU 04</span><h1>{{ selectedOrder.id }}</h1></div><b data-testid="shopping-order-detail-status">{{ orderStatusLabel(selectedOrder.status) }}</b></header><section class="cu-pass"><div><span>READY CODE</span><i class="fas fa-qrcode"></i><strong>{{ selectedOrder.id.slice(-6).toUpperCase() }}</strong></div><aside><span>ORDER TOTAL</span><strong data-testid="shopping-order-detail-total">{{ formatOrderTotal(selectedOrder) }}</strong><p>{{ selectedOrder.itemCount }} ITEMS / STORE PICKUP</p></aside></section><section class="cu-detail-items"><article v-for="item in selectedOrder.items" :key="item.id" :data-testid="`shopping-order-detail-item-${item.productId}`"><span>ZONE A</span><h2>{{ item.title }}</h2><p>{{ item.quantity }} × {{ formatOrderItemSubtotal({ ...item,quantity:1 }) }}</p><strong>{{ formatOrderItemSubtotal(item) }}</strong></article></section><section class="cu-detail-timeline" data-testid="shopping-order-detail-timeline"><h2>STORE PREP LOG</h2><article v-for="event in selectedOrder.events||[]" :key="event.id" :data-testid="`shopping-order-detail-event-${event.id}`"><i class="fas fa-store"></i><div><strong>{{ logisticsEventTypeLabel(event.type) }}</strong><p>{{ event.summary||event.title }}</p><span>{{ formatLogisticsDate(event.createdAt) }}</span></div></article><p v-if="!selectedOrder.events?.length" data-testid="shopping-order-detail-timeline-empty">NO STORE EVENTS</p></section><footer><button data-testid="shopping-order-detail-complete" :disabled="!canCompleteOrder(selectedOrder)" @click="emit('complete-order',selectedOrder.id)">COLLECTED</button><button data-testid="shopping-order-detail-cancel" :disabled="!canCancelOrder(selectedOrder)" @click="emit('cancel-order',selectedOrder.id)">CANCEL</button><button data-testid="shopping-order-detail-delete" @click="emit('delete-order',selectedOrder.id)">DELETE</button></footer></section>
  </main>
</template>
